        function ModifyQrCodeElements(formId, action = "blur") {
            // Select QR code elements
            const elements = {
                scanImgBorder: document.querySelector(`${formId} #scanImgBorderId`),
                blurQrCode: document.querySelector(`${formId} #blur_qrcode`),
                blurScanupiHeading: document.querySelector(`${formId} #blur_scanupi_heading`),
                showQrCodeBtn: document.querySelector(`${formId} #orange_show_qrcode_btn`),
                scanupiHeading: document.querySelector(`${formId} #scanupi_heading`),
                qrCodeElement: document.querySelector(`${formId} #qrcode`),
                qrCodeLoader: document.querySelector(`${formId} #qrCodeLoader`)
            };
            if (action === "blur") {
                // Show blurred QR code
                elements.scanupiHeading.style.display = "none";
                elements.qrCodeElement.innerHTML = ""; // Clear QR code
                elements.qrCodeElement.style.display = "none";
                elements.blurQrCode.style.display = "block";
                elements.showQrCodeBtn.style.display = "block";
                elements.blurScanupiHeading.style.display = "block";
                elements.scanImgBorder.classList.replace("scan-img-border-org", "scan-img-border");
            } else {
                // Show original QR code
                elements.blurQrCode.style.display = "none";
                elements.qrCodeLoader.style.display = "none"; // Hide loader
                elements.blurScanupiHeading.style.display = "none";
                elements.scanupiHeading.style.display = "block";
                elements.qrCodeElement.style.display = "block";
                elements.scanImgBorder.classList.replace("scan-img-border", "scan-img-border-org");
            }
        }
        // Declare intervals at a higher scope so they are accessible throughout the script
        var countdownInterval;
        var statusInterval;
        // When the pageloads && if any change occur in addon, loadQrCode() function will call
        function loadQrCode() {
            if (country == 98) {
                qrcode_id.value = qrcode_image_content.value = "";
                QRCodeFormIds.forEach(formId => ModifyQrCodeElements(formId, "blur"));
                // Clear both intervals
                clearInterval(countdownInterval);
                clearInterval(statusInterval);
                statusInterval = null; // Reset statusInterval
                var serializedData = $("#riUpiIdForm").serialize();
                serializedData += "&generate_upi_qrcode=1";
                $.ajax({
                    type: "POST",
