                async: true,
                success: function(result) {
                    if (result.RESPONSECODE == 1 && result.ERRCODE == 0) {
                        console.log(result);
                    }
                }
            });
            event.preventDefault();
            var riUpiIdForm = "#riUpiIdForm";
            var riUpiMobileNoForm = "#riUpiMobileNoForm";
            QRCodeFormIds.forEach(function(formId) {
                document.querySelector(`${formId} #orange_show_qrcode_btn`).style.display = "none";
                document.querySelector(`${formId} #qrCodeLoader`).style.display = "block";
            });
            // Check the QR Code input textbox. If it is empty, display the loader until the textbox receives a value.
            function checkQrCodeIdValue() {
                var qrcodeIdValue = qrcode_id.value;
                var qrcodeImageContentValue = qrcode_image_content.value;
                if (qrcodeIdValue && qrcodeImageContentValue) {
                    clearInterval(qrCodeIdInterval);
                    proceedWithQrCodeGeneration(qrcodeIdValue, qrcodeImageContentValue);
                }
            }
            var qrCodeIdInterval = setInterval(checkQrCodeIdValue, 1); // Check every 1ms
            function proceedWithQrCodeGeneration(qrcodeIdValue, qrcodeImageContentValue) {
                // ===========================================================================
                var totalTime = 240; // 4 minutes in seconds
                QRCodeFormIds.forEach(function(formId) {
                    const qrCodeElement = document.querySelector(`${formId} #qrcode`);
                    ModifyQrCodeElements(formId, "original");
                    new QRCode(qrCodeElement, {
                        text: qrcodeImageContentValue,
                        width: 165, // Set the width of the QR code
                        height: 165 // Set the height of the QR code
                    });
                });
                const riUpiIdFormCountdownElement = document.querySelector(`${riUpiIdForm} #countdown`);
                const riUpiMobileNoFormCountdownElement = document.querySelector(`${riUpiMobileNoForm} #countdown`);
                // Check the QR Code status every 3 seconds
                function getQrCodeStatus(qrcodeIdValue) {
                    $.ajax({
                        type: "POST",
                        url: "https://api.mobileshop.com/apppayment/qrcode_status.php",
                        data: "qr_code_id=" + qrcodeIdValue,
                        async: true,
                        success: function(result) {
                            if (result.RESPONSECODE == 1 && result.ERRCODE == 0) {
                                console.log("Your payment was successful");
                                clearInterval(countdownInterval);
                                clearInterval(statusInterval);
                                window.location.href = "https://mobileshop.com/payments/razorpayupiupgrade.php?upitype=qrcode&razorpay_qrcode_orderid=" + qrcodeIdValue;
                            } else {
                                console.log("Status=>", result.MSG);
                            }
                        }
                    });
                }

                function updateCountdown() {
                    if (totalTime >= 0) {
                        // If totalTime is not yet zero and statusInterval is not running, start it
                        if (!statusInterval) {
                            statusInterval = setInterval(checkQrCodeStatus, 3000);
                        }
                        // Calculate minutes and seconds
                        var minutes = Math.floor(totalTime / 60);
                        var seconds = totalTime % 60;
                        seconds = seconds < 10 ? '0' + seconds : seconds;
                        QRCodeFormIds.forEach(formId => {
                            document.querySelector(`${formId} #countdown`).innerHTML = `Time left: ${minutes}:${seconds}`;
                        });
                        // Decrease total time by 1 second
                        totalTime--;
                    } else {
                        // Timer has finished
                        QRCodeFormIds.forEach(formId => {
                            document.querySelector(`${formId} #countdown`).innerHTML = "Time is up!";
                            ModifyQrCodeElements(formId, "blur");
                        });
                        // Clear both intervals
                        clearInterval(countdownInterval);
                        clearInterval(statusInterval);
                    }
                }

                function checkQrCodeStatus() {
                    getQrCodeStatus(qrcodeIdValue);
                }
                // Update the countdown every second
                countdownInterval = setInterval(updateCountdown, 1000);
                // Initial call to display the countdown immediately
                updateCountdown();
                // ===========================================================================
                const serializedData = $(QRCodeFormIds[0]).serialize() + "&upiqrcodeflag=1&orderid=" + qrcodeIdValue;
                $.ajax({
                    type: "POST",
                    url: "https://mobileshop.com/payments/razorpayupi.php",
                    data: serializedData,
                    success: function(result) {
                        console.log(result);
                    }
                });
            }
            return false;
        }

