                const input = document.querySelector('.cardPaymentNo');

                let debounceTimer = null;
                let lastTriggeredState = null; // 'under', 'called', or 'empty'

                // Time to wait after user stops typing
                const TYPING_PAUSE_DELAY = 500;

                input.addEventListener('input', () => {
                    const rawValue = input.value;
                    const digitsOnly = rawValue.replace(/\D/g, '');
                    const digitLength = digitsOnly.length;

                    // Clear any existing typing timer
                    clearTimeout(debounceTimer);

                    // Case: Input is completely empty
                    if (rawValue === '') {
                        if (lastTriggeredState !== 'empty') {
                            checkCardBinSeries('');
                            lastTriggeredState = 'empty';
                        }
                        return;
                    }

                    // Case: Input has fewer than 9 digits
                    if (digitLength < 9) {
                        if (lastTriggeredState !== 'under') {
                            checkCardBinSeries(digitsOnly);
                            lastTriggeredState = 'under';
                        }
                        return;
                    }

                    // Case: Input has 9+ digits, wait for typing to stop
                    debounceTimer = setTimeout(() => {
                        if (lastTriggeredState !== 'called') {
                            checkCardBinSeries(digitsOnly);
                            lastTriggeredState = 'called';
                        }
                    }, TYPING_PAUSE_DELAY);

                    // Update temporary state while user is typing
                    lastTriggeredState = 'typing';
                });
        function checkCvv(cardnumber) {
            if (cardnumber == "") {
                return false;
            }
            document.getElementById("hidden_cardCvvLength").value = 0;
            document.riCreditDebitForm.vpc_CardSecurityCode.setAttribute("maxLength", 3);
            cardnumber = cardnumber.split(" ").join("");
            cardnumber = cardnumber.split("-").join("");
            const cards = [{
                    name: "American Express",
                    length: "15",
                    prefixes: "34,37",
                    NUM: 1,
                    cardType: "PAMXV_Y"
                },
                {
                    name: "Diners Club Carte Blanche",
                    length: "14",
                    prefixes: "300,301,302,303,304,305",
                    NUM: 2,
                    cardType: "CBDCLB_Y"
                },
                {
                    name: "Diners Club",
                    length: "14,16",
                    prefixes: "305,36,38,54,55",
                    NUM: 3,
                    cardType: "CBDCLB_Y"
                },
                {
                    name: "Diners Club Enroute",
                    length: "15",
                    prefixes: "2014,2149",
                    NUM: 4,
                    cardType: "CBDCLB_Y"
                },
                {
                    name: "JCB",
                    length: "16",
                    prefixes: "35",
                    NUM: 5,
                    cardType: "PJCB_Y"
                }
            ];
            for (var i = 0; i < cards.length; i++) {
                var prefix = cards[i]["prefixes"].split(",");
                var cLength = cards[i]["length"].split(",");
                for (var j = 0; j < prefix.length; j++) {
                    if (cardnumber.substring(0, prefix[j].length) == prefix[j]) {
                        console.log(cardnumber.substring(0, prefix[j].length));
                        for (var k = 0; k < cLength.length; k++) {
                            if (cLength[k] == cardnumber.length) {
                                document.getElementById("hidden_cardType").value = cards[i]["cardType"];
                                if (cards[i]["NUM"] == 1 || cards[i]["NUM"] == 5) {
                                    document.getElementById("hidden_cardCvvLength").value = 1;
                                    document.riCreditDebitForm.vpc_CardSecurityCode.setAttribute("maxLength", 4);
                                }
                            }
                        }
                    }
                }
            }
        }
        document.addEventListener("DOMContentLoaded", function() {
            // Credit/Debit card validation button enable ------------------------
            const cardNumberInput = document.getElementsByName("vpc_CardNum")[0];
            const cardExpiryMonthInput = document.getElementsByName("cardExpiryMonth")[0];
            const cardExpiryYearInput = document.getElementsByName("cardExpiryYear")[0];
            const cvvInput = document.getElementsByName("vpc_CardSecurityCode")[0];
            const riNriCardSubmitBtn = document.getElementById("riNriCardSubmitBtn");

            function validateCardNumber(number) {
                const cleanedNumber = number.replace(/\s+/g, '').replace(/-/g, '');
                const regex = /^\d{13,19}$/;
                return regex.test(cleanedNumber);
            }

            function validateExpirationDate(month, year) {
                const monthRegex = /^(0[1-9]|1[0-2])$/;
                const yearRegex = /^[0-9]{2}$/;
                if (!monthRegex.test(month) || !yearRegex.test(year)) return false;
                const currentDate = new Date();
                const inputDate = new Date(`20${year}`, month - 1, 1);
                // Set input date to the last day of the month
                inputDate.setMonth(inputDate.getMonth() + 1);
                inputDate.setDate(0);
                return inputDate >= new Date(currentDate.getFullYear(), currentDate.getMonth(), 1);
            }

            function validateCVV(cvv) {
                const regex = /^[0-9]{3,4}$/;
                return regex.test(cvv);
            }

            function validateCardForm() {
                console.log("validateCardForm");
                const cardNumberValid = validateCardNumber(cardNumberInput.value);
                const expirationDateValid = validateExpirationDate(cardExpiryMonthInput.value, cardExpiryYearInput.value);
                const cvvValid = validateCVV(cvvInput.value);
                const isDomesticCard = $("#isDomesticCard").val();
                const billingCountrySel = $("#billing_country_sel").val();
                let billCountryValid = false;
                if((isDomesticCard === "1") || (isDomesticCard === "0" && billingCountrySel !== "0")){
                    billCountryValid = true;
                }else{
                    billCountryValid = false;
                }

                if (cardNumberValid && expirationDateValid && cvvValid && billCountryValid) {
                    riNriCardSubmitBtn.classList.remove("gray-btn");
                    riNriCardSubmitBtn.classList.add("yellow-btn");
                } else {
                    riNriCardSubmitBtn.classList.add("gray-btn");
                    riNriCardSubmitBtn.classList.remove("yellow-btn");
                }
            }
            if (cardNumberInput && cardExpiryMonthInput && cardExpiryYearInput && cvvInput && riNriCardSubmitBtn) {
                cardNumberInput.addEventListener('input', validateCardForm);
                cardExpiryMonthInput.addEventListener('input', validateCardForm);
                cardExpiryYearInput.addEventListener('input', validateCardForm);
                cvvInput.addEventListener('input', validateCardForm);
            }

            const targetNode = document.getElementById('billingCountryDropdown');

            const observer = new MutationObserver(function(mutationsList, observer) {
                validateCardForm(); // Call your function on any change
            });

            observer.observe(targetNode, {
                childList: true,       // Detect added/removed children
                subtree: true,         // Detect changes in nested elements
                characterData: true    // Detect text changes
            });

            // Doorstep validation button enable ------------------------
            const addressFlatName = document.getElementById("address_flat_name");
            const addressStreetName = document.getElementById("address_street_name");
            var riDoorStepSubmitBtn = document.getElementById("riDoorStepSubmitBtn");

