        /*  GET CARD TYPE DETAILS */
        function GetCardType(number) {
            var re = new RegExp("^4");
            if (number.match(re) != null)
                return "Visa";
            re = new RegExp("^(508[5-9][0-9]{12})|(6069[8-9][0-9]{11})|(607[0-8][0-9]{12})|(6079[0-8][0-9]{11})|(608[0-5][0-9]{12})|(6521[5-9][0-9]{11})|(652[2-9][0-9]{12})|(6530[0-9]{12})|(6531[0-4][0-9]{11})");
            if (number.match(re) != null)
                return "Rupaycard";
            // Diners Club Carte Blanche (prefix 300–305)
            re = new RegExp("^(300|301|302|303|304|305)");
            if (number.match(re) != null)
                return "Diners Club Carte Blanche";
            // Diners Club Enroute (prefix 2014, 2149)
            re = new RegExp("^(2014|2149)");
            if (number.match(re) != null)
                return "Diners Club Enroute";
            // Diners Club (prefix 305, 36, 38, 54, 55)
            re = new RegExp("^(305|36|38|54|55)");
            if (number.match(re) != null)
                return "Diners Club";
            re = new RegExp("^(34|37)");
            if (number.match(re) != null)
                return "American Express";
            re = new RegExp("^5[1-5]|222[1-9]|22[3-9][0-9]|2[3-6][0-9]{2}|27[01][0-9]|2720[0-9]");
            if (number.match(re) != null)
                return "Mastercard";
            re = new RegExp("^(5018|5020|5038|5044|5046|5047|5048|5049|5081|6002|6038|6220|6304|6759|6761|6762|6763)");
            if (number.match(re) != null)
                return "Maestrocard";
            return 0;
        }
