        /* NRI Card Validation */
        function ValidateCreditCardNRI() {
            // START CCAVENUE Gateway params
            const screenHeight = screen.height;
            const screenWidth = screen.width;
            const colorDepth = screen.colorDepth;
            const isJavaEnabled = navigator.javaEnabled();
            const timeZone = new Date().getTimezoneOffset();
            $('input[name="screenHeight"]').val(screenHeight);
            $('input[name="screenWidth"]').val(screenWidth);
            $('input[name="colorDepth"]').val(colorDepth);
            $('input[name="isJavaEnabled"]').val(isJavaEnabled);
            $('input[name="timeZone"]').val(timeZone);
            // END CCAVENUE Gateway params
            var NriCreditDebitForm = this.document.NriCreditDebitForm;
            var n = document.getElementById('cardnumber').value;
            var nameExp = /^[a-zA-Z. ]+$/;
            var addressExp = /^[0-9a-zA-Z. ]+$/;
            var billing_country_sel = $("#billing_country_sel").val();
            var isDomesticCard = $("#isDomesticCard").val();
            $('.ErrorContainer').remove();
            if (IsEmpty(document.NriCreditDebitForm.CREDITCARDNUMBER, 'text')) {
                NriCreditDebitForm.CREDITCARDNUMBER.focus();
                var errDiv = $('<div class="ErrorContainer">Please enter your card number</div>');
                $('.cardNumberErr').append(errDiv);
                return false;
            }
            if (!ValidateNo(document.NriCreditDebitForm.CREDITCARDNUMBER.value, "0123456789 -")) {
                NriCreditDebitForm.CREDITCARDNUMBER.focus();
                var errDiv = $('<div class="ErrorContainer">Invalid Creditcard Number</div>');
                $('.cardNumberErr').append(errDiv);
                return false;
            }
            n = n.split("-").join("");
            n = n.split(" ").join("");
            n1 = n.substring(0, 1);
            n2 = n.substring(0, 2);
            if (n.length <= 0) {
                var errDiv = $('<div class="ErrorContainer">Please enter your card number</div>');
                $('.cardNumberErr').append(errDiv);
                NriCreditDebitForm.CREDITCARDNUMBER.focus();
                return false;
            }
            if (n.length > 16 || n.length < 13) {
                var errDiv = $('<div class="ErrorContainer">Your credit card number must contain 13 to 16 digits</div>');
                $('.cardNumberErr').append(errDiv);
                NriCreditDebitForm.CREDITCARDNUMBER.focus();
                return false;
            }
            if ((n2 == 34) || (n2 == 37)) {
                if (n.length < 15) {
                    var errDiv = $('<div class="ErrorContainer">Your credit card number must contain 15 digits</div>');
                    $('.cardNumberErr').append(errDiv);
                    NriCreditDebitForm.CREDITCARDNUMBER.focus();
                    return false;
                }
            }
            if (n2 == 35) {
                if (n.length < 16) {
                    var errDiv = $('<div class="ErrorContainer">Your credit card number must contain 16 digits</div>');
                    $('.cardNumberErr').append(errDiv);
                    NriCreditDebitForm.CREDITCARDNUMBER.focus();
                    return false;
                }
            }
            if (n1 == 3) {
                if (n.length < 14) {
                    var errDiv = $('<div class="ErrorContainer">Your credit card number must contain 14 digits</div>');
                    $('.cardNumberErr').append(errDiv);
                    NriCreditDebitForm.CREDITCARDNUMBER.focus();
                    return false;
                }
            }
            if (n1 == 4 || n1 == 5) {
                if (n.length < 16) {
                    var errDiv = $('<div class="ErrorContainer">Your credit card number must contain 16 digits</div>');
                    $('.cardNumberErr').append(errDiv);
                    NriCreditDebitForm.CREDITCARDNUMBER.focus();
                    return false;
                }
            }
            cardExpiryMonthVal = Number(NriCreditDebitForm.EXPMON.value);
            cardExpiryYearVal = Number(NriCreditDebitForm.EXPYEAR.value);
            if (cardExpiryMonthVal == "" && cardExpiryYearVal == "") {
                NriCreditDebitForm.EXPMON.focus();
                var errDiv = $('<div class="ErrorContainer">Please select Expiry Date</div>');
                $('.cardExpiryMonthErr').append(errDiv);
                return false;
            }
            if (cardExpiryMonthVal == "" && cardExpiryYearVal != "") {
                NriCreditDebitForm.EXPMON.focus();
                var errDiv = $('<div class="ErrorContainer">Please select Expiry Month</div>');
                $('.cardExpiryMonthErr').append(errDiv);
                return false;
            }
            if (cardExpiryYearVal == "") {
                NriCreditDebitForm.EXPYEAR.focus();
                var errDiv = $('<div class="ErrorContainer">Please select Expiry Year</div>');
                $('.cardExpiryYearErr').append(errDiv);
                return false;
            }
            const currentDate = new Date();
            const currentMonth = currentDate.getMonth() + 1; // getMonth() returns months from 0-11
            const currentYear = currentDate.getFullYear() % 100; // get last two digits of the year
            if (cardExpiryYearVal < currentYear || (cardExpiryYearVal === currentYear && cardExpiryMonthVal < currentMonth)) {
                NriCreditDebitForm.EXPMON.focus();
                NriCreditDebitForm.EXPYEAR.focus();
                var errDiv = $('<div class="ErrorContainer">Your card has expired</div>');
                $('.cardExpiryMonthErr').append(errDiv);
                $('.cardExpiryYearErr').append(errDiv);
                return false;
            }
            if (NriCreditDebitForm.CREDITCARDCVV.value == '') {
                NriCreditDebitForm.CREDITCARDCVV.focus();
                var errDiv = $('<div class="ErrorContainer">Please enter Card Verification Number</div>');
                $('.cardVerificationNoErr').append(errDiv);
                return false;
            }
            if (document.NriCreditDebitForm.CREDITCARDCVV.value.length < 3 || document.NriCreditDebitForm.CREDITCARDCVV.value.length > 4) {
                NriCreditDebitForm.CREDITCARDCVV.focus();
                var errDiv = $('<div class="ErrorContainer">Invalid Card Verification Number</div>');
                $('.cardVerificationNoErr').append(errDiv);
                return false;
            }
            if (!ValidateNo(document.NriCreditDebitForm.CREDITCARDCVV.value, "0123456789")) {
                NriCreditDebitForm.CREDITCARDCVV.focus();
                var errDiv = $('<div class="ErrorContainer">Invalid Card Verification Number</div>');
                $('.cardVerificationNoErr').append(errDiv);
                return false;
            }
            if(isDomesticCard == 0){
                if(billing_country_sel == 0){
                    var errDiv = $('<div class="ErrorContainer">Select Billing Country</div>');
                    $('.billingCountrySelNoErr').append(errDiv);
                    return false;
                }else{
                    $('.billingCountrySelNoErr').empty();
                }
            }else{
                $('.billingCountrySelNoErr').empty();
            }
            $('#CreditForm [type="submit"]').attr('disabled', 'disabled').css("cssText", "background: #ABABAB !important;border-width: medium medium 0!important;");
            document.getElementById("creditButtonnew").innerHTML = '<div class="pay-loading-dots"><div class="pay-loading-dots-dot"></div><div class="pay-loading-dots-dot"></div><div class="pay-loading-dots-dot"></div></div>';
            return true;
        }
