        var giveCardSpace = function(CardTextId, e) {
            //alert(CardTextId);
            charLength = $("#" + CardTextId).attr("value").length;
            var PassingValue = $("#" + CardTextId).attr("value");
            var PassingValue = PassingValue.replace(/[^0-9 ]/g, "");
            var PassingValue = PassingValue.split(" ").join("");
            var amex = PassingValue.match(/^3[47][0-9]+$/);
            var maestro = PassingValue.match(/^(5018|5020|5038|5044|5046|5047|5048|5049|6002|6038|6220|6304|6759|6761|6762|6763)/); //maest
            var visa = PassingValue.match(/^4[0-9]+$/);

            function checkCharCodes(e) {
                if (e.keyCode === 8) {
                    return false;
                } //backspace
                if (e.keyCode === 35) {
                    return false;
                } //end
                if (e.keyCode === 36) {
                    return false;
                } //home
                if (e.keyCode === 46) {
                    return false;
                } //delete
                if (e.keyCode >= 37 && e.keyCode <= 40) {
                    return false;
                } //up,down,left,right arrow
                if (e.shiftKey == true) {
                    return false;
                } //shift key pressed
                if (e.shiftKey == true && e.keyCode == 9) {
                    return false;
                } //shift+tab key pressed
                if (e.shiftKey == true && (e.keyCode == 37 || e.keyCode == 38 || e.keyCode == 39 || e.keyCode == 40)) {
                    return false;
                } //shift key with arrow keys
                return true;
            }
            if ((e.type === "keyup" || e.type === "paste") && (checkCharCodes(e))) {
                var pointerPos = $("#" + CardTextId).val();
                //alert(pointerPos);
                var cardNum = SplitCardFormat = $("#" + CardTextId).val();
                if (e.type === "paste") {
                    cardNum = cardNum.replace(/[^0-9 ]/g, "");
                }
                var startFormatCardVal = $.trim(cardNum.substr(0, pointerPos));
                var endFormatCardVal = $.trim(cardNum.substr(pointerPos, cardNum.length));
                if (typeof(pointerPos) != "undefined") {
                    var cardNumVal = $("#" + CardTextId).attr("value").split(" ").join("");
                    if (e.type === "paste") {
                        cardNumVal = cardNumVal.replace(/[^0-9 ]/g, "");
                    }
                    var cardNumValSplit = cardNumVal.split("");
                    if (amex) {
                        var SplitCardFormat1 = cardNumValSplit.slice(0, 4).toString().split(",").join("");
                        var SplitCardFormat2 = cardNumValSplit.slice(4, 10).toString().split(",").join("");
                        var SplitCardFormat3 = cardNumValSplit.slice(10, 15).toString().split(",").join("");
                        var finalCard = SplitCardFormat1 + " " + SplitCardFormat2 + " " + SplitCardFormat3;
                        var final = $.trim(finalCard);
                        startFormatCardVal = startFormatCardVal.replace(/\s/g, "");
                        if (startFormatCardVal.length == 5) {
                            pointerPos = startFormatCardVal.length + 1;
                        }
                        if (startFormatCardVal.length == 11) {
                            pointerPos = startFormatCardVal.length + 2;
                        }
                        $("#" + CardTextId).val(final);
                        $("#" + CardTextId).val(final);
                        if (e.type === "paste") {
                            var pasteLength = final.length;
                            $("#" + CardTextId).val(final);
                        }
                    } else if (maestro) {
                        // do nothing
                    } else {
                        var SplitCardFormat1 = cardNumValSplit.slice(0, 4).toString().split(",").join("");
                        var SplitCardFormat2 = cardNumValSplit.slice(4, 8).toString().split(",").join("");
                        var SplitCardFormat3 = cardNumValSplit.slice(8, 12).toString().split(",").join("");
                        var SplitCardFormat4 = cardNumValSplit.slice(12, 16).toString().split(",").join("");
                        var finalCard = SplitCardFormat1 + " " + SplitCardFormat2 + " " + SplitCardFormat3 + " " + SplitCardFormat4;
                        var final = $.trim(finalCard);
                        startFormatCardVal = startFormatCardVal.replace(/\s/g, "");
                        if (startFormatCardVal.length == 5) {
                            pointerPos = startFormatCardVal.length + 1;
                        }
                        if (startFormatCardVal.length == 9) {
                            pointerPos = startFormatCardVal.length + 2;
                        }
                        if (startFormatCardVal.length == 13) {
                            pointerPos = startFormatCardVal.length + 3;
                        }
                        $("#" + CardTextId).val(final);
                        $("#" + CardTextId).val(final);
                        if (e.type === "paste") {
                            var pasteLength = final.length;
                            $("#" + CardTextId).val(final);
                        }
                    }
                }
            }
        }

