        function countrySearch() {
            const query = $('#SearchCountryName').val().toLowerCase();
            const $results = $('#countryresults');
            let selCountryKey = $("#billing_country_sel").val();
            $results.empty(); // clear old results
            let found = false;
            // Loop through the countryHash object

            $.each(countryHash, function (key, value) {
                if (value.toLowerCase().includes(query)) {
                    if(selCountryKey == key || country_display == key){
                        $results.append(`<li class="selected" data-value=${key} onclick="selCountryName('${key}','${value}')"><span>${value}</span></li>`);
                    }else{
                        $results.append(`<li data-value=${key} onclick="selCountryName('${key}','${value}')"><span>${value}</span></li>`);
                    }
                    found = true;
                }
            });

             if (!found) {
                $results.prepend('<p style="list-style: none;padding: 12px 20px;color: #000;font-family: Lato;font-size: 14px;font-style: normal;font-weight: 400;line-height: 16px;letter-spacing: 0.42px;border-bottom: 1px solid #F1F1F1;">No results found</p>');
            }
        }

        function selCountryName(countryKey, countryName){
            $("#billing_country_sel").val(countryKey);
            $("#billingCountryDropdown").text(countryName);
            $('#SearchCountryName').val('');
            countryModal.style.display = "none";
            document.body.style.overflow = "auto";
            document.body.style.height = "auto";
        }

        function verifyCardPayment() {
            const riNriCardSubmitBtn = document.getElementById("riNriCardSubmitBtn");
            const cardNumber = $(".cardPaymentNo").val();
            const expMonth = $(".cardPaymentMonth").val();
            const expYear = $(".cardPaymentYear").val();
            const cvv = $(".cardPaymentCVV").val();
            const isDomesticCard = $("#isDomesticCard").val();
            const billingCountrySel = $("#billing_country_sel").val();

            const cardNumberValid = /^\d{13,19}$/.test(cardNumber.replace(/\s+|-/g, ''));
            const expirationDateValid = (() => {
                if (!/^(0[1-9]|1[0-2])$/.test(expMonth) || !/^\d{2}$/.test(expYear)) return false;
                const now = new Date();
                const expiry = new Date(`20${expYear}`, expMonth); // first day of next month
                return expiry > now;
            })();
            const cvvValid = /^[0-9]{3,4}$/.test(cvv);

            const billCountryValid = (isDomesticCard === "1") || (isDomesticCard === "0" && billingCountrySel !== "0");

            riNriCardSubmitBtn.classList.toggle("yellow-btn", cardNumberValid && expirationDateValid && cvvValid && billCountryValid);
            riNriCardSubmitBtn.classList.toggle("gray-btn", !(cardNumberValid && expirationDateValid && cvvValid && billCountryValid));
        }

